package com.kai.automusic;import android.content.*;import android.os.*;public class Boot extends BroadcastReceiver{public void onReceive(Context c,Intent i){android.content.SharedPreferences p=c.getSharedPreferences("music",0);Schedule.plan(c);boolean power=Intent.ACTION_POWER_CONNECTED.equals(i.getAction());if(power?p.getBoolean("auto",true):p.getBoolean("boot",true)){Intent s=new Intent(c,PlayerService.class).setAction(power?"POWER":"BOOT");try{if(Build.VERSION.SDK_INT>=26)c.startForegroundService(s);else c.startService(s);}catch(Exception e){}}}}